// END LAYOUT 2

// used in all the actions
bool same_area(double sx, double sy, double dx, double dy) {
    int i;
    bool x_s_in, y_s_in, x_d_in, y_d_in;
    for (i = 0; i < N_A; i++)
    {
        x_s_in = sx > FLOOR[i][0][0] && sx < FLOOR[i][3][0];
        y_s_in = sy > FLOOR[i][0][1] && sy < FLOOR[i][1][1];
        x_d_in = dx > FLOOR[i][0][0] && dx < FLOOR[i][3][0];
        y_d_in = dy > FLOOR[i][0][1] && dy < FLOOR[i][1][1];
        if ((x_s_in && y_s_in) && (x_d_in && y_d_in)) // start and dest in same area
            return true;
    }
    return false;
}

// used in all the actions
double pt_dist(double x1, double x2, double y1, double y2) {
    double xdifference = x2-x1;
    double ydifference = y2-y1;
    return sqrt((xdifference*xdifference)+(ydifference*ydifference));
}

/**
 * Checks if the given coordinates (x, y) are inside ANY of the valid floor areas.
 * Returns true if the position is valid, false if it is in a forbidden area.
 */
bool isValidPosition(double x, double y) {
    // Iterate through all defined areas in the layout
    for (i : int[0, N_A - 1]) {
        // Extract boundaries from the rectangle definition
        // Assuming Point 0 is Bottom-Left (min) and Point 2 is Top-Right (max)
        double x_min = FLOOR[i][0][0];
        double y_min = FLOOR[i][0][1];
        double x_max = FLOOR[i][2][0];
        double y_max = FLOOR[i][2][1];

        // Check if the point is strictly inside the current rectangle
        if (x > x_min && x < x_max && y > y_min && y < y_max) {
            return true; // The agent is safe, found a valid floor
        }
    }

    // If the loop finishes without returning true, the agent is outside all valid areas
    return false;
}



